export function invalidReturnValue(expected, name, value) {
    return codedError(new NativeTypeError(`Expected ${expected} to be returned from the "${name}" function but got ${determineSpecificType(value)}.`), "ERR_INVALID_RETURN_VALUE");
}
export function ambiguousArgument(name, reason) {
    return codedError(new NativeTypeError(`The "${name}" argument is ambiguous. ${reason}`), "ERR_AMBIGUOUS_ARGUMENT");
}
export function constructCallRequired(name) {
    return codedError(new NativeTypeError(`Cannot call constructor ${name} without \`new\``), "ERR_CONSTRUCT_CALL_REQUIRED");
}
export function illegalConstructor() {
    return codedError(new NativeTypeError("Illegal constructor"), "ERR_ILLEGAL_CONSTRUCTOR");
}
