export function invalidThis(name) {
    return codedError(new NativeTypeError(`Value of "this" must be of type ${name}`), "ERR_INVALID_THIS");
}
export function deprecatedNodeApi(name, replacement) {
    const suffix = replacement ? ` Use ${replacement} instead.` : "";
    return codedError(new NativeError(`The deprecated Node.js API ${name} is not supported by jco-std.${suffix}`), "ERR_JCO_UNSUPPORTED_DEPRECATED_NODE_API");
}
export function unsupportedNodeApi(api, reason) {
    return codedError(new NativeError(`${api} is not supported in a WebAssembly component: ${reason}`), "ERR_JCO_UNSUPPORTED_NODE_API");
}
/** Error code carried by every unsupported-API failure Jco raises for Node builtins. */
export const UNSUPPORTED_CODE = "ERR_JCO_UNSUPPORTED_NODE_API";
/** Error code for APIs Node itself has deprecated, which Jco declines to implement. */
export const DEPRECATED_CODE = "ERR_JCO_UNSUPPORTED_DEPRECATED_NODE_API";
